        if not identity:
            this.set("expression", self._parse_range())
        elif not this.args.get("start") and self._match(TokenType.NUMBER, advance=False):
            args = self._parse_csv(self._parse_bitwise)
            this.set("start", seq_get(args, 0))
            this.set("increment", seq_get(args, 1))

        self._match_r_paren()

        # Check for STORED or VIRTUAL keywords for computed columns
        if not identity and this.expression:
            persisted = None
            if self._match_text_seq("STORED"):
                persisted = True
            elif self._match_text_seq("VIRTUAL"):
                persisted = False

            if persisted is not None:
                return self.expression(
                    exp.ComputedColumnConstraint, 
                    this=this.expression, 
                    persisted=persisted
                )

    return this

